#!/usr/bin/env python3
"""runtime/patch_amax8_grid_47149.py against the pristine pin files.

The PR touches CUDA JIT headers -- not executable CPU-side. The fixtures are
the byte-exact pristine 7d996300 files (block_amax.cuh fell back to a
whole-file pair in the patcher; mega_moe_pre_dispatch.cuh carries 13 anchored
regions). Checks: patch applies, is idempotent, and the patched text carries
the structural markers (once.h include, kWaves=2 occupancy-capped grid-stride
walk, strided persistent pre-dispatch); anchor drift fails loudly.
"""
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PATCHER = ROOT / 'runtime' / 'patch_amax8_grid_47149.py'

AMAX = '#pragma once\n\n#include <sgl_kernel/tensor.h>\n#include <sgl_kernel/utils.h>\n\n#include <sgl_kernel/utils.cuh>\n#include <sgl_kernel/vec.cuh>\n\n#include <dlpack/dlpack.h>\n#include <tvm/ffi/container/tensor.h>\n\n#include <algorithm>\n#include <cstdint>\n#include <limits>\n#include <type_traits>\n\nnamespace sglang {\n\n/// Level-one keys of the two-level indexer: the max of each kBlockTokens-score\n/// block, the row\'s newest block forced to +inf. Scores and keys are each fp32\n/// or bf16; a bf16 score\'s max is exact in either key type. Contract: BlockAmaxKernel.\ntemplate <typename InT, typename OutT>\nstruct BlockAmaxConfig {\n  using DType = InT;\n  using KeyT = OutT;\n  static constexpr uint32_t kBlockTokens = 8;  // scores per key\n  static constexpr uint32_t kBlockSize = 512;\n  static constexpr uint32_t kOccupancy = 4;\n  // One fp32 block is 32 B: a single load on Blackwell, two 16 B loads before it.\n  // A bf16 block is one 16 B load anywhere.\n  static constexpr uint32_t kBlockBytes = kBlockTokens * sizeof(DType);\n  static constexpr uint32_t kVecBytes = std::min<uint32_t>(kBlockBytes, device::kMaxVecBytes);\n  static constexpr uint32_t kVecSize = kVecBytes / sizeof(DType);\n  static constexpr uint32_t kVecsPerBlock = kBlockTokens / kVecSize;\n  static constexpr uint32_t kNumItems = 64 / kBlockBytes;  // 64B scores (16 registers) per thread\n  static constexpr uint32_t kKeysPerCTA = kBlockSize * kNumItems;\n  static_assert(kVecsPerBlock * kVecSize == kBlockTokens);\n  using vec_t = device::AlignedVector<DType, kVecSize>;\n};\n\ntemplate <typename InT, typename OutT>\nstruct BlockAmaxParams {\n  const InT* __restrict__ scores;\n  OutT* __restrict__ amax_scores;\n  const int32_t* __restrict__ seq_len;\n  int64_t stride_scores;       // in elements\n  int64_t stride_amax_scores;  // in elements\n  uint32_t topk;               // rows with <= topk blocks are skipped, 0 = never skip\n};\n\n/// grid = (rows, ceil(max_keys / kKeysPerCTA)); a CTA owns kKeysPerCTA consecutive\n/// keys of one row, a thread kNumItems keys kBlockSize apart (coalesced loads).\ntemplate <bool kUsePDL, typename InT, typename OutT>\n__global__ __launch_bounds__(BlockAmaxConfig<InT, OutT>::kBlockSize, BlockAmaxConfig<InT, OutT>::kOccupancy)  //\n    void amax8_varlen_kernel(const __grid_constant__ BlockAmaxParams<InT, OutT> params) {\n  using namespace device;\n  using C = BlockAmaxConfig<InT, OutT>;\n  using vec_t = typename C::vec_t;\n  const auto bx = blockIdx.x;\n  const auto by = blockIdx.y;\n  const auto tx = threadIdx.x;\n\n  PDLWaitPrimary<kUsePDL>();  // seq_len and scores are the previous kernels\' outputs\n  const auto seq_len = static_cast<uint32_t>(params.seq_len[bx]);\n  const auto num_keys = (seq_len + C::kBlockTokens - 1) / C::kBlockTokens;\n  const auto first_key = by * C::kKeysPerCTA;\n  if (num_keys <= params.topk || first_key >= num_keys) {\n    return PDLTriggerSecondary<kUsePDL>();\n  }\n  const auto* __restrict__ in = params.scores + bx * params.stride_scores;\n  auto* __restrict__ out = params.amax_scores + bx * params.stride_amax_scores;\n\n  vec_t vec[C::kNumItems][C::kVecsPerBlock];\n#pragma unroll\n  for (uint32_t i = 0; i < C::kNumItems; ++i) {\n    const auto idx = first_key + tx + i * C::kBlockSize;\n    if (idx < num_keys) {\n#pragma unroll\n      for (uint32_t v = 0; v < C::kVecsPerBlock; ++v) {\n        vec[i][v].load(in, idx * C::kVecsPerBlock + v);\n      }\n    }\n  }\n  // The dependent grid may start its prologue now; its griddepcontrol.wait still\n  // covers every store below (it waits for this grid to complete).\n  PDLTriggerSecondary<kUsePDL>();\n\n#pragma unroll\n  for (uint32_t i = 0; i < C::kNumItems; ++i) {\n    const auto idx = first_key + tx + i * C::kBlockSize;\n    if (idx < num_keys) {\n      // fmaxf and __hmax2 ignore a NaN score, torch.amax would propagate it\n      if constexpr (std::is_same_v<InT, float>) {\n        float key = vec[i][0][0];\n#pragma unroll\n        for (uint32_t v = 0; v < C::kVecsPerBlock; ++v) {\n#pragma unroll\n          for (uint32_t j = 0; j < C::kVecSize; ++j) {\n            key = fmaxf(key, vec[i][v][j]);\n          }\n        }\n        const auto fp32_inf = std::numeric_limits<float>::infinity();\n        out[idx] = cast<OutT>(idx + 1 == num_keys ? fp32_inf : key);\n      } else {\n        const auto vec_ptr = reinterpret_cast<bf16x2_t*>(vec[i][0].data());\n        static_assert(C::kVecSize % 2 == 0);\n        bf16x2_t key2 = vec_ptr[0];\n#pragma unroll\n        for (uint32_t v = 1; v < C::kVecsPerBlock * C::kVecSize / 2; ++v) {\n          key2 = __hmax2(key2, vec_ptr[v]);\n        }\n        const auto key = __hmax(key2.x, key2.y);\n        const auto bf16_inf = cast<bf16_t>(std::numeric_limits<float>::infinity());\n        out[idx] = cast<OutT>(idx + 1 == num_keys ? bf16_inf : key);\n      }\n    }\n  }\n}\n\n/// Host entry: `amax_scores[b, i] = max(scores[b, 8 i : 8 i + 8])` for\n/// `i < ceil(seq_len[b] / 8)`, the last of them +inf; rows with at most `topk`\n/// blocks untouched. `scores` (`InT`) rows must keep every block of 8 aligned\n/// (stride % 8 == 0); `amax_scores` is `OutT`. Each type is fp32 or bf16.\n/// The grid covers `amax_scores`\' width, so the caller sizes it for the longest\n/// row: `seq_len[b] <= 8 * amax_scores.shape[1]` for every row (not checked).\ntemplate <bool kPDL, typename InT, typename OutT>\nstruct BlockAmaxKernel {\n  static void amax8_varlen(\n      const tvm::ffi::TensorView scores,\n      const tvm::ffi::TensorView seq_lens,\n      const tvm::ffi::TensorView amax_scores,\n      const uint32_t topk) {\n    using namespace host;\n    using C = BlockAmaxConfig<InT, OutT>;\n    auto B = SymbolicSize{"batch_size"};\n    auto L = SymbolicSize{"max_seq_len"};\n    auto K = SymbolicSize{"max_keys"};\n    auto device_ = SymbolicDevice{};\n    device_.set_options<kDLGPU>();\n    TensorMatcher({B, L})  // scores\n        .with_strides({-1, 1})\n        .with_dtype<typename C::DType>()\n        .with_device(device_)\n        .ensure_alignment(C::kBlockBytes)\n        .verify(scores);\n    TensorMatcher({B})  // seq_lens\n        .with_dtype<int32_t>()\n        .with_device(device_)\n        .verify(seq_lens);\n    TensorMatcher({B, K})  // amax_scores\n        .with_strides({-1, 1})\n        .with_dtype<typename C::KeyT>()\n        .with_device(device_)\n        .verify(amax_scores);\n    const auto max_keys = K.unwrap();  // ceil(longest row / 8), sized by the caller\n    const auto params = BlockAmaxParams<InT, OutT>{\n        .scores = static_cast<const InT*>(scores.data_ptr()),\n        .amax_scores = static_cast<OutT*>(amax_scores.data_ptr()),\n        .seq_len = static_cast<const int32_t*>(seq_lens.data_ptr()),\n        .stride_scores = scores.stride(0),\n        .stride_amax_scores = amax_scores.stride(0),\n        .topk = topk,\n    };\n    const auto grid = dim3(\n        static_cast<uint32_t>(B.unwrap()),\n        static_cast<uint32_t>(div_ceil(max_keys, static_cast<int64_t>(C::kKeysPerCTA))));\n    LaunchKernel(grid, C::kBlockSize, device_.unwrap())\n        .config({.use_pdl = kPDL})\n        .launch(amax8_varlen_kernel<kPDL, InT, OutT>, params);\n  }\n};\n\n}  // namespace sglang\n'

MEGA = '#include <sgl_kernel/tensor.h>\n#include <sgl_kernel/utils.h>\n\n#include <sgl_kernel/math.cuh>\n#include <sgl_kernel/type.cuh>\n#include <sgl_kernel/utils.cuh>\n#include <sgl_kernel/vec.cuh>\n#include <sgl_kernel/warp.cuh>\n\n#include <sgl_kernel/deepseek_v4/fp8_utils.cuh>\n\n#include <algorithm>\n#include <cstdint>\n#include <cuda_fp8.h>\n\nnamespace sglang {\n\nusing deepseek_v4::fp8::cast_to_ue8m0;\nusing deepseek_v4::fp8::pack_fp8;\n\n// CUDA block-size ceiling. One CTA per token row, so a row wider than\n// kMaxBlockThreads * 8 bf16 elements is covered in several strided chunks.\ninline constexpr uint32_t kMaxBlockThreads = 1024;\n\nstruct MegaMoEPreDispatchParams {\n  const bf16_t* __restrict__ x;            // [num_tokens, hidden]\n  const int32_t* __restrict__ topk_idx;    // [num_tokens, top_k]\n  const float* __restrict__ topk_weights;  // [num_tokens, top_k]\n\n  fp8_e4m3_t* __restrict__ buf_x;        // [padded_max, hidden]\n  int32_t* __restrict__ buf_x_sf;        // row-major int32 [P, G/4]\n  int64_t* __restrict__ buf_topk_idx;    // [padded_max, top_k]\n  float* __restrict__ buf_topk_weights;  // [padded_max, top_k]\n  int32_t* __restrict__ shared_x_sf;     // column-major, BLOCK_M-paged scales\n\n  uint64_t buf_x_sf_stride_bytes;\n  uint64_t shared_x_sf_col_stride;\n  uint32_t shared_block_m;\n  uint32_t num_tokens;\n  uint32_t padded_max;\n  uint32_t hidden;\n  uint32_t num_groups;  // hidden / group_size\n  uint32_t top_k;\n};\n\n// kGroupSize must match the consuming MoE\'s activation scale group (quant_group_size).\n// kMultiChunk covers rows too wide for one chunk per thread. It is a template\n// parameter rather than a runtime check because this kernel is issue-bound: the\n// loop bookkeeping alone costs ~10% on the rows that fit a single chunk.\ntemplate <uint32_t kGroupSize, bool kUsePDL, bool kMultiChunk, bool kWriteSharedSF, bool kCopyTopk>\n__global__ __launch_bounds__(kMaxBlockThreads, 2) void  //\n    mega_moe_pre_dispatch_kernel(const MegaMoEPreDispatchParams __grid_constant__ params) {\n  using namespace device;\n\n  constexpr uint32_t kVecElems = 8;  // 8 bf16 = 16B load per thread\n  static_assert(kGroupSize % kVecElems == 0, "group_size must be a multiple of 8");\n  constexpr uint32_t kThreadsPerGroup = kGroupSize / kVecElems;\n  static_assert(kMaxBlockThreads % kThreadsPerGroup == 0, "block must stride by whole quant groups");\n  using InputVec = AlignedVector<bf16x2_t, kVecElems / 2>;\n  using OutputVec = AlignedVector<fp8x2_e4m3_t, kVecElems / 2>;\n\n  const uint32_t bid = blockIdx.x;\n  const uint32_t tid = threadIdx.x;\n\n  PDLWaitPrimary<kUsePDL>();\n  if (bid < params.num_tokens) {\n    // ---- Quantize path: one CTA per valid token ----\n\n    const uint32_t token_id = bid;\n    const auto token_in = params.x + static_cast<uint64_t>(token_id) * params.hidden;\n    const auto token_out = params.buf_x + static_cast<uint64_t>(token_id) * params.hidden;\n    uint32_t shared_row = 0;\n    if constexpr (kWriteSharedSF) {\n      const uint32_t m = token_id % params.shared_block_m;\n      shared_row = token_id / params.shared_block_m * ((params.shared_block_m + 127u) / 128u * 128u) + m / 128u * 128u +\n                   m % 32u * 4u + m % 128u / 32u;\n    }\n\n    const auto quantize_chunk = [&](uint32_t chunk) {\n      InputVec in_vec;\n      in_vec.load(token_in, chunk);\n\n      float local_max = 0.0f;\n      float vals[kVecElems];\n#pragma unroll\n      for (uint32_t i = 0; i < kVecElems / 2; ++i) {\n        const auto [v0, v1] = cast<fp32x2_t>(in_vec[i]);\n        vals[2 * i + 0] = v0;\n        vals[2 * i + 1] = v1;\n        local_max = fmaxf(local_max, fmaxf(fabsf(v0), fabsf(v1)));\n      }\n\n      // Absmax across the kThreadsPerGroup threads that cover one group.\n      local_max = warp::reduce_max<kThreadsPerGroup>(local_max);\n\n      const float absmax = fmaxf(local_max, 1e-10f);\n      const float raw_scale = absmax / math::FP8_E4M3_MAX;\n      const uint32_t ue8m0_exp = cast_to_ue8m0(raw_scale);\n      // 2^-ue8m0_exp as fp32 (equivalent to 1 / __uint_as_float(ue8m0 << 23)).\n      const float inv_scale = __uint_as_float((127u + 127u - ue8m0_exp) << 23);\n\n      OutputVec out_vec;\n#pragma unroll\n      for (uint32_t i = 0; i < kVecElems / 2; ++i) {\n        out_vec[i] = pack_fp8(vals[2 * i + 0] * inv_scale, vals[2 * i + 1] * inv_scale);\n      }\n      out_vec.store(token_out, chunk);\n\n      // One thread per group writes its UE8M0 byte into the row-major int32-\n      // packed layout. DeepGEMM may pad each row to preserve TMA alignment.\n      const uint32_t group_id = chunk / kThreadsPerGroup;\n      const uint32_t within_group_id = chunk % kThreadsPerGroup;\n      if (within_group_id == 0 && group_id < params.num_groups) {\n        const uint64_t byte_off = static_cast<uint64_t>(token_id) * params.buf_x_sf_stride_bytes + group_id;\n        reinterpret_cast<uint8_t*>(params.buf_x_sf)[byte_off] = static_cast<uint8_t>(ue8m0_exp);\n        if constexpr (kWriteSharedSF) {\n          const uint64_t off = shared_row + static_cast<uint64_t>(group_id / 4u) * params.shared_x_sf_col_stride;\n          reinterpret_cast<uint8_t*>(params.shared_x_sf)[off * sizeof(int32_t) + group_id % 4u] =\n              static_cast<uint8_t>(ue8m0_exp);\n        }\n      }\n    };\n\n    if constexpr (kMultiChunk) {\n      // The reduce_max in quantize_chunk shuffles with a full-warp mask:\n      // blockDim.x is a multiple of kThreadsPerGroup and the host pins the tail\n      // iteration to whole warps, so each quant group stays on converged\n      // consecutive lanes.\n      const uint32_t num_chunks = params.hidden / kVecElems;\n      for (uint32_t chunk = tid; chunk < num_chunks; chunk += blockDim.x) {\n        quantize_chunk(chunk);\n      }\n    } else {\n      quantize_chunk(tid);\n    }\n\n    // Copy this token\'s topk row (no alignment assumptions; top_k is small).\n    if (kCopyTopk && tid < params.top_k) {\n      const uint32_t off = token_id * params.top_k + tid;\n      params.buf_topk_idx[off] = params.topk_idx[off];\n      params.buf_topk_weights[off] = params.topk_weights[off];\n    }\n  } else {\n    // ---- Pad path: trailing blocks fill [num_tokens, padded_max) with (-1, 0) ----\n    const uint32_t copy_bid = bid - params.num_tokens;\n    const uint32_t pad_base = params.num_tokens * params.top_k;\n    const uint32_t slot = pad_base + copy_bid * blockDim.x + tid;\n    const uint32_t total_slots = params.padded_max * params.top_k;\n\n    if (slot < total_slots) {\n      params.buf_topk_idx[slot] = -1;\n      params.buf_topk_weights[slot] = 0.0f;\n    }\n  }\n  PDLTriggerSecondary<kUsePDL>();\n}\n\n// ---- Host wrapper\n// ------------------------------------------------------------------------------------------------------------------------\n\ntemplate <int64_t kGroupSize, bool kUsePDL, bool kWriteSharedSF, bool kCopyTopk>\nstruct MegaMoEPreDispatchKernel {\n  static_assert(kGroupSize == 32 || kGroupSize == 64 || kGroupSize == 128, "unsupported group_size");\n  static constexpr auto kernel_one_chunk =\n      mega_moe_pre_dispatch_kernel<static_cast<uint32_t>(kGroupSize), kUsePDL, false, kWriteSharedSF, kCopyTopk>;\n  static constexpr auto kernel_multi_chunk =\n      mega_moe_pre_dispatch_kernel<static_cast<uint32_t>(kGroupSize), kUsePDL, true, kWriteSharedSF, kCopyTopk>;\n\n  static void\n  run(const tvm::ffi::TensorView x,\n      const tvm::ffi::TensorView topk_idx,\n      const tvm::ffi::TensorView topk_weights,\n      const tvm::ffi::TensorView buf_x,\n      const tvm::ffi::TensorView buf_x_sf,\n      const tvm::ffi::TensorView buf_topk_idx,\n      const tvm::ffi::TensorView buf_topk_weights,\n      const tvm::ffi::Optional<tvm::ffi::TensorView> shared_x_sf,\n      const int64_t shared_block_m) {\n    using namespace host;\n\n    auto device = SymbolicDevice{};\n    auto M = SymbolicSize{"num_tokens"};\n    auto P = SymbolicSize{"padded_max"};\n    auto H = SymbolicSize{"hidden"};\n    auto K = SymbolicSize{"top_k"};\n    auto G4 = SymbolicSize{"num_groups_div_4"};\n    device.set_options<kDLCUDA>();\n\n    TensorMatcher({M, H})  // input x\n        .with_dtype<bf16_t>()\n        .with_device(device)\n        .verify(x);\n    if constexpr (kCopyTopk) {\n      TensorMatcher({M, K})  // topk_idx\n          .with_dtype<int32_t>()\n          .with_device(device)\n          .verify(topk_idx);\n      TensorMatcher({M, K})  // topk_weights\n          .with_dtype<float>()\n          .with_device(device)\n          .verify(topk_weights);\n    }\n    // DeepGEMM versions expose this fp8 dispatch buffer either as raw int8\n    // storage or as torch.float8_e4m3fn; the kernel writes fp8 bytes in both.\n    TensorMatcher({P, H})  // buf.x\n        .with_dtype<int8_t, fp8_e4m3_t>()\n        .with_device(device)\n        .verify(buf_x);\n    // DeepGEMM exposes only the logical G scale bytes but may pad its physical\n    // row stride to 16 bytes for TMA (for example, H=2304 is 72B -> 80B).\n    TensorMatcher({P, G4})  // buf_x_sf\n        .with_strides({-1, 1})\n        .with_dtype<int32_t>()\n        .with_device(device)\n        .verify(buf_x_sf);\n    TensorMatcher({P, K})  // buf.topk_idx\n        .with_dtype<int64_t>()\n        .with_device(device)\n        .verify(buf_topk_idx);\n    TensorMatcher({P, K})  // buf.topk_weights\n        .with_dtype<float>()\n        .with_device(device)\n        .verify(buf_topk_weights);\n\n    const auto num_tokens = static_cast<uint32_t>(M.unwrap());\n    const auto padded_max = static_cast<uint32_t>(P.unwrap());\n    const auto hidden = static_cast<uint32_t>(H.unwrap());\n    const auto top_k = static_cast<uint32_t>(K.unwrap());\n    const auto num_groups_div_4 = static_cast<uint32_t>(G4.unwrap());\n\n    RuntimeCheck(num_tokens <= padded_max, "num_tokens must not exceed padded_max");\n    RuntimeCheck(hidden % kGroupSize == 0, "hidden must be a multiple of group_size");\n    const auto num_groups = hidden / static_cast<uint32_t>(kGroupSize);\n    RuntimeCheck(num_groups == num_groups_div_4 * 4u, "num_groups must be a multiple of 4");\n    RuntimeCheck(\n        buf_x_sf.stride(0) >= static_cast<int64_t>(num_groups_div_4),\n        "buf_x_sf row stride is smaller than its logical row width");\n    const auto buf_x_sf_stride_bytes = static_cast<uint64_t>(buf_x_sf.stride(0)) * sizeof(int32_t);\n    RuntimeCheck(buf_x_sf_stride_bytes % 16u == 0, "buf_x_sf row stride must be 16B-aligned");\n    RuntimeCheck(\n        reinterpret_cast<uintptr_t>(buf_x_sf.data_ptr()) % 16u == 0, "buf_x_sf base address must be 16B-aligned");\n    RuntimeCheck(hidden % 8u == 0, "hidden must be a multiple of 8 (16B bf16 loads)");\n    const auto num_chunks = hidden / 8u;\n    const auto block_size = std::min(num_chunks, kMaxBlockThreads);\n    const bool one_chunk_per_thread = num_chunks <= kMaxBlockThreads;\n    // The quant group absmax is a full-warp-mask shuffle, so either the row fits\n    // one iteration or its tail iteration is entered by whole warps.\n    RuntimeCheck(\n        one_chunk_per_thread || num_chunks % device::kWarpThreads == 0,\n        "hidden above 8192 must be a multiple of 256 so the tail quant chunks fill whole warps");\n    RuntimeCheck(block_size >= top_k, "top_k must fit into one quant CTA");\n\n    int32_t* shared_sf_ptr = nullptr;\n    uint64_t shared_sf_stride = 0;\n    if constexpr (kWriteSharedSF) {\n      RuntimeCheck(kGroupSize == 32, "shared MegaMoE scales require group_size=32");\n      RuntimeCheck(shared_block_m > 0, "shared_block_m must be positive");\n      auto S = SymbolicSize{"shared_sf_rows"};\n      const auto sf = shared_x_sf.value();\n      TensorMatcher({S, G4}).with_strides({1, -1}).with_dtype<int32_t>().with_device(device).verify(sf);\n      const auto rows = (num_tokens + shared_block_m - 1) / shared_block_m * ((shared_block_m + 127) / 128 * 128);\n      RuntimeCheck(S.unwrap() >= rows, "shared scale buffer is too small for shared_block_m");\n      RuntimeCheck(sf.stride(1) >= S.unwrap(), "shared scale columns must not overlap");\n      shared_sf_ptr = static_cast<int32_t*>(sf.data_ptr());\n      shared_sf_stride = sf.stride(1);\n    }\n\n    const auto pad_slots = kCopyTopk ? (padded_max - num_tokens) * top_k : 0u;\n    const uint32_t num_pad_blocks = pad_slots == 0 ? 0u : ((pad_slots + block_size - 1u) / block_size);\n    const auto num_total_blocks = num_tokens + num_pad_blocks;\n\n    const auto params = MegaMoEPreDispatchParams{\n        .x = static_cast<const bf16_t*>(x.data_ptr()),\n        .topk_idx = static_cast<const int32_t*>(topk_idx.data_ptr()),\n        .topk_weights = static_cast<const float*>(topk_weights.data_ptr()),\n        .buf_x = static_cast<fp8_e4m3_t*>(buf_x.data_ptr()),\n        .buf_x_sf = static_cast<int32_t*>(buf_x_sf.data_ptr()),\n        .buf_topk_idx = static_cast<int64_t*>(buf_topk_idx.data_ptr()),\n        .buf_topk_weights = static_cast<float*>(buf_topk_weights.data_ptr()),\n        .shared_x_sf = shared_sf_ptr,\n        .buf_x_sf_stride_bytes = buf_x_sf_stride_bytes,\n        .shared_x_sf_col_stride = shared_sf_stride,\n        .shared_block_m = static_cast<uint32_t>(shared_block_m),\n        .num_tokens = num_tokens,\n        .padded_max = padded_max,\n        .hidden = hidden,\n        .num_groups = num_groups,\n        .top_k = top_k,\n    };\n\n    if (num_total_blocks == 0) return;\n    if (one_chunk_per_thread) {\n      LaunchKernel(num_total_blocks, block_size, device.unwrap())  //\n          .enable_pdl(kUsePDL)(kernel_one_chunk, params);\n    } else {\n      LaunchKernel(num_total_blocks, block_size, device.unwrap())  //\n          .enable_pdl(kUsePDL)(kernel_multi_chunk, params);\n    }\n  }\n};\n\n}  // namespace sglang\n'


def run(base):
    return subprocess.run([sys.executable, '-I', str(PATCHER), str(base)],
                          capture_output=True, text=True)


def main():
    with tempfile.TemporaryDirectory() as d:
        base = Path(d)
        amax = base / 'sglang/kernels/jit/csrc/deepseek_v4/block_amax.cuh'
        mega = base / 'sglang/kernels/jit/csrc/deepseek_v4/mega_moe_pre_dispatch.cuh'
        for p, text in ((amax, AMAX), (mega, MEGA)):
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text)

        assert '#include <sgl_kernel/once.h>' not in AMAX
        assert 'kWaves' not in AMAX, 'fixture sanity: pristine has no wave cap'

        first = run(base)
        assert first.returncode == 0, first.stderr
        after = {p: p.read_text() for p in (amax, mega)}
        second = run(base)
        assert second.returncode == 0 and 'already patched' in second.stdout, second.stdout
        assert all(p.read_text() == t for p, t in after.items())

        amax_t = amax.read_text()
        assert '#include <sgl_kernel/once.h>' in amax_t
        assert 'static constexpr uint32_t kWaves = 2;' in amax_t
        assert 'host::init_once(' in amax_t
        assert 'cudaOccupancyMaxActiveBlocksPerMultiprocessor' in amax_t
        assert 'max_grid_y' in amax_t
        amax_loops = 'first_key +=' in amax_t and 'gridDim.y' in amax_t
        assert amax_loops, 'patched: amax walks key chunks grid-stride'
        mega_t = mega.read_text()
        assert '#include <sgl_kernel/once.h>' in mega_t
        assert 'kChunksPerThread' in mega_t, 'patched: chunk-per-thread variants'
        assert 'host::init_once(' in mega_t
        assert 'kernel_two_chunks' in mega_t

        # whole-file anchor drift fails loudly
        assert '#pragma once' in AMAX
        amax.write_text(AMAX.replace('#pragma once', '#pragma drifted'))
        drifted = run(base)
        assert drifted.returncode == 1 and 're-derive from sglang#47149' in drifted.stderr, \
            drifted.stderr

    print('test_patch_amax8_grid_47149 PASS')


